const { ethers } = require('ethers');

const RAW_OUTPUT = '';

async function main() {
  const decoded = ethers.AbiCoder.defaultAbiCoder().decode(['bytes', 'bytes'], RAW_OUTPUT);
  console.log('Decoded as (bytes, bytes):');
  console.log('simmedInput length:', decoded[0].length / 2 - 1);
  console.log('actualOutput length:', decoded[1].length / 2 - 1);
  console.log('actualOutput value:', decoded[1]);
  
  if (decoded[1] !== '0x') {
    // If actualOutput is not empty, decode it as (address dkmsPaymentAddress, bytes dkmsPublicKey)
    try {
      const decodedActual = ethers.AbiCoder.defaultAbiCoder().decode(['address', 'bytes'], decoded[1]);
      console.log('Decoded actualOutput:', decodedActual);
    } catch (err) {
      console.error('Failed to decode actualOutput:', err.message);
    }
  }
}

main().catch(console.error);
